{"command":"cat << 'EOF' > /prediction.json
{
    "vllm/attention/ops/triton_prefill_attention.py": {
        "_fwd_kernel": "@triton.jit\ndef _fwd_kernel(\n    Q,\n    K,\n    V,\n    sm_scale,\n    B_Start_Loc,\n    B_Seqlen,\n    Out,\n    stride_qbs,\n    stride_qh,\n    stride_kbs,\n    stride_kh,\n    stride_vbs,\n    stride_vh,\n    stride_obs,\n    stride_oh,\n    kv_group_num: tl.constexpr,\n    BLOCK_M: tl.constexpr,\n    BLOCK_DMODEL: tl.constexpr,\n    BLOCK_N: tl.constexpr,\n    IS_CAUSAL: tl.constexpr,\n    SLIDING_WINDOW_Q: tl.constexpr,\n    SLIDING_WINDOW_K: tl.constexpr,\n    Lk: tl.constexpr,\n):\n    cur_batch = tl.program_id(0)\n    cur_head = tl.program_id(1)\n    start_m = tl.program_id(2)\n\n    cur_kv_head = cur_head // kv_group_num\n\n    cur_batch_seq_len = tl.load(B_Seqlen + cur_batch)\n    cur_batch_in_all_start_index = tl.load(B_Start_Loc + cur_batch)\n\n    block_start_loc = start_m * BLOCK_M\n\n    # initialize offsets\n    offs_m = block_start_loc + tl.arange(0, BLOCK_M)\n    offs_n = tl.arange(0, BLOCK_N)\n    offs_d = tl.arange(0, BLOCK_DMODEL)\n\n    # load q\n    q_ptr = Q + (cur_batch_in_all_start_index + offs_m[:, None]) * stride_qbs + cur_head * stride_qh + offs_d[None, :]\n    q = tl.load(q_ptr, mask=offs_m[:, None] < cur_batch_seq_len, other=0.0)\n\n    # initialize pointer to m and l\n    m_i = tl.zeros([BLOCK_M], dtype=tl.float32) - float('inf')\n    l_i = tl.zeros([BLOCK_M], dtype=tl.float32)\n    acc = tl.zeros([BLOCK_M, BLOCK_DMODEL], dtype=tl.float32)\n\n    # loop over k, v and update accumulator\n    end_n = cur_batch_seq_len\n    if IS_CAUSAL:\n        end_n = tl.minimum(end_n, block_start_loc + BLOCK_M)\n\n    for start_n in range(0, end_n, BLOCK_N):\n        offs_n_new = start_n + offs_n\n        # load k, v\n        k_ptr = K + (cur_batch_in_all_start_index + offs_n_new[None, :]) * stride_kbs + cur_kv_head * stride_kh + offs_d[:, None]\n        v_ptr = V + (cur_batch_in_all_start_index + offs_n_new[:, None]) * stride_vbs + cur_kv_head * stride_vh + offs_d[None, :]\n\n        k = tl.load(k_ptr, mask=offs_n_new[None, :] < cur_batch_seq_len, other=0.0)\n\n        # dot product\n        qk = tl.dot(q, k)\n        qk *= sm_scale\n\n        # apply mask\n        if IS_CAUSAL:\n            qk = tl.where(offs_m[:, None] >= offs_n_new[None, :], qk, float(\"-inf\"))\n        \n        if SLIDING_WINDOW_Q > 0:\n            qk = tl.where(offs_m[:, None] - offs_n_new[None, :] <= SLIDING_WINDOW_Q, qk, float(\"-inf\"))\n        \n        if SLIDING_WINDOW_K > 0:\n            qk = tl.where(offs_n_new[None, :] - offs_m[:, None] <= SLIDING_WINDOW_K, qk, float(\"-inf\"))\n\n        qk = tl.where(offs_n_new[None, :] < cur_batch_seq_len, qk, float(\"-inf\"))\n\n        # update m_i and l_i\n        m_i_new = tl.maximum(m_i, tl.max(qk, 1))\n        p = tl.exp(qk - m_i_new[:, None])\n        l_i = l_i * tl.exp(m_i - m_i_new) + tl.sum(p, 1)\n        \n        v = tl.load(v_ptr, mask=offs_n_new[:, None] < cur_batch_seq_len, other=0.0)\n        acc = acc * tl.exp(m_i - m_i_new)[:, None] + tl.dot(p.to(v.dtype), v)\n        m_i = m_i_new\n\n    acc = acc / l_i[:, None]\n    \n    # store output\n    out_ptr = Out + (cur_batch_in_all_start_index + offs_m[:, None]) * stride_obs + cur_head * stride_oh + offs_d[None, :]\n    tl.store(out_ptr, acc.to(Out.dtype.element_ty), mask=offs_m[:, None] < cur_batch_seq_len)"
    }
}
EOF
"}

